import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-DCZUiBeJ.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S05/S05E22.html","title":"S05E22 The One with Joey's Big Break","lang":"zh-CN","frontmatter":{"title":"S05E22 The One with Joey's Big Break","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":119},"git":{"createdTime":1780654155000,"updatedTime":1780664804000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":37.74,"words":11323},"filePathRelative":"语言/英语/Friends老友记/S05/S05E22.md"}`),a={name:`S05E22.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-joey-s-big-break" tabindex="-1"><a class="header-anchor" href="#the-one-with-joey-s-big-break"><span>The One with Joey&#39;s Big Break</span></a></h1><blockquote><p><em>乔伊的大突破</em></p></blockquote><p>The One With Joey&#39;s Big Break</p><blockquote><p>乔伊的大突破</p></blockquote><p><strong>Teleplay by:</strong> Wil Calhoun</p><blockquote><p>威尔卡尔霍恩</p></blockquote><p><strong>Story by:</strong> Shana Goldberg-Meehan</p><blockquote><p>沙娜·戈德伯格·米汉</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Central Perk, everyone but Phoebe are there reading. Rachel is sitting on the couch flanked by Ross and Monica. She suddenly stops reading and starts blinking her left eye as if it&#39;s bothering her. The problem is that Joey is on her left and thinks she&#39;s winking at him and winks back. Ross is watching this and isn&#39;t quite sure of what to make of it.</em></p><blockquote><p>🎬 <em>中央公园，除了菲比，其他人都在看书。瑞秋坐在沙发上，罗斯和莫妮卡站在旁边。她突然停止看书，开始眨左眼，好像这让她很不安。问题是乔伊在她左边，以为她在向他眨眼，然后又眨了眨眼。罗斯正在看，不知道该怎么办接受它。</em></p></blockquote><p><strong>Ross Geller:</strong> What&#39;s going on?</p><blockquote><p>发生什么事了？</p></blockquote><p><strong>Rachel Green:</strong> Well, my eye is a little itchy.</p><blockquote><p>嗯，我的眼睛有点痒。</p></blockquote><p><em>(Ross turns to look at Joey.)</em></p><blockquote><p><em>（罗斯转身看着乔伊。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Uhhh, mine too! Yeah.</p><blockquote><p>哦，我的也是！是 啊</p></blockquote><p><strong>Monica Geller:</strong> (To Rachel) Wow! It&#39;s really red! You should go see my eye doctor.</p><blockquote><p>（对瑞秋）哇！它真的是红色的！你应该去看我的眼科医生。</p></blockquote><p><strong>Rachel Green:</strong> Richard? I&#39;m not gonna go see your ex-boyfriend!</p><blockquote><p>理查德？我不会去见你的前男友！</p></blockquote><p><strong>Chandler Bing:</strong> Oh, Richard. That&#39;s all I ever hear, Richard, Richard, Richard!</p><blockquote><p>哦，理查德。这就是我所听到的，Richard，Richard，Richard！</p></blockquote><p><strong>Monica Geller:</strong> Since we&#39;ve been going out, I think I&#39;ve mentioned his name twice!</p><blockquote><p>自从我们约会以来，我想我已经两次提到他的名字了！</p></blockquote><p><strong>Chandler Bing:</strong> Okay, so Richard, Richard!</p><blockquote><p>好吧，理查德，理查德！</p></blockquote><p><strong>Monica Geller:</strong> It&#39;s not Richard! Okay? It&#39;s this new guy and he&#39;s really good.</p><blockquote><p>不是理查德！可以是这个新来的家伙，他真的很棒。</p></blockquote><p><strong>Rachel Green:</strong> Well, I&#39;m sorry I&#39;m not going to an eye doctor!</p><blockquote><p>嗯，对不起，我不去看眼科医生了！</p></blockquote><p><strong>Ross Geller:</strong> Oh God, here we go!</p><blockquote><p>哦，天哪，我们开始了！</p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Ross Geller:</strong> Anytime anything comes close to touching her eye or anyone else&#39;s she like freaks out. Watch! Watch! (He takes his finger and moves it towards his eye.)</p><blockquote><p>只要有什么东西接近她的眼睛或任何其他人的眼睛，她就会像疯子一样。注意！注意！（他拿起手指，朝眼睛方向移动。）</p></blockquote><p><strong>Rachel Green:</strong> (flinches) Ross! Come on! That&#39;s all right! Fine--Okay, I have a weird thing about my eye. Can we not talk about it please?</p><blockquote><p>（退缩）罗斯！来吧没关系！好吧，我的眼睛有点怪。我们可以不谈这个吗？</p></blockquote><p><strong>All:</strong> All right, fine.</p><blockquote><p>好的，好的。</p></blockquote><p><strong>Monica Geller:</strong> Hey Rach, remember that great song, Me, Myself, and I? (And on the &quot;I&quot; part she mimics poking her eye.)</p><blockquote><p>嘿，瑞秋，还记得那首很棒的歌吗，我，我自己，还有我？（在“我”部分，她模仿戳眼睛。）</p></blockquote><p><strong>Rachel Green:</strong> (flinches again) Monica! Come on!</p><blockquote><p>（再次畏缩）莫妮卡！来吧</p></blockquote><p><strong>Ross Geller:</strong> Hey, does anybody want to get some lunch? All those in favor say I? (Pokes his eye)</p><blockquote><p>嘿，有人想吃午饭吗？所有赞成的人都说我？（戳了戳他的眼睛）</p></blockquote><p><strong>Rachel Green:</strong> (freaks) Ross! Stop it! Come on!</p><blockquote><p>（怪胎）罗斯！住手！来吧</p></blockquote><p><strong>Chandler Bing:</strong> How much did I love The King and I? (Oh, you get the point by now.)</p><blockquote><p>我有多爱国王和我？（哦，你现在明白了。）</p></blockquote><p><strong>Rachel Green:</strong> Chandler!</p><blockquote><p>钱德勒！</p></blockquote><p><strong>Joey Tribbiani:</strong> Me too! Me too! Me too! (Yeah, he does the same thing.)</p><blockquote><p>我也是！我也是！我也是！（是的，他也这么做。）</p></blockquote><p><strong>Rachel Green:</strong> Just stop it! Come on!</p><blockquote><p>住手！来吧</p></blockquote><p><em>(Joey howls in pain and holds his eye.)</em></p><blockquote><p><em>（乔伊痛苦地嚎叫着，并紧握着眼睛。）</em></p></blockquote><p><strong>Chandler Bing:</strong> You okay there man?</p><blockquote><p>你没事吧，伙计？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, I got too excited!</p><blockquote><p>是啊，我太兴奋了！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross, Chandler, Monica, and Phoebe are eating breakfast.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋、罗斯、钱德勒、莫妮卡和菲比正在吃早餐。</em></p></blockquote><p><strong>Ross Geller:</strong> All right, I gotta go. I&#39;m taking Ben to the park.</p><blockquote><p>好吧，我得走了。我要带本去公园。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh, give him a kiss for me!</p><blockquote><p>哦，帮我吻他一下！</p></blockquote><p><strong>Ross Geller:</strong> All right, bye!</p><blockquote><p>好的，再见！</p></blockquote><p><strong>Monica Geller:</strong> Bye!</p><blockquote><p>再见！</p></blockquote><p><strong>Phoebe Buffay:</strong> Bye!</p><blockquote><p>再见！</p></blockquote><p><strong>Ross Geller:</strong> Later! (Exits.)</p><blockquote><p>待会儿！（退出。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (after he&#39;s gone) I am so sorry you got caught in the middle of that. I didn&#39;t mean to be so out there. I am furious with him!</p><blockquote><p>（他走后）我很抱歉你被抓住了。我本不想在外面这样。我对他很生气！</p></blockquote><p><strong>Chandler Bing:</strong> Wow umm, calm down.</p><blockquote><p>哇，嗯，冷静点。</p></blockquote><p><strong>Phoebe Buffay:</strong> I&#39;m trying, but man that guy can push my buttons!</p><blockquote><p>我在努力，但那家伙可以按我的按钮！</p></blockquote><p><strong>Monica Geller:</strong> Why are so mad at him?</p><blockquote><p>你为什么这么生他的气？</p></blockquote><p><strong>Phoebe Buffay:</strong> Look, I don&#39;t wanna talk about it. Okay?</p><blockquote><p>听着，我不想谈这个。可以</p></blockquote><p><strong>Monica Geller:</strong> Well, it just seems that…</p><blockquote><p>看来…</p></blockquote><p><strong>Phoebe Buffay:</strong> You wanna be on my list too? Keep talking! Has anyone seem my list by the way?</p><blockquote><p>你也想在我的名单上吗？继续说！顺便问一下，有人看过我的名单吗？</p></blockquote><p><strong>Chandler Bing:</strong> Uh, no Pheebs. What&#39;s it look like?</p><blockquote><p>嗯，没有菲比。它看起来像什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh, it&#39;s a piece of paper and it says, &quot;Ross&quot; on it.</p><blockquote><p>嗯，是一张纸，上面写着“罗斯”。</p></blockquote><p><strong>Joey Tribbiani:</strong> (entering, depressed) Hey. I just got off the phone with Estelle and guess what. (Pause, then very excitedly) I GOT THE LEAD IN A MOVIE!!!!!!</p><blockquote><p>（进来，沮丧地）嘿。我刚和Estelle通完电话，你猜怎么着。（停顿，然后非常激动地）我在一部电影中获得了主角！！！！！！</p></blockquote><p><strong>Chandler Bing:</strong> You got the lead in a movie? That&#39;s amazing! What&#39;s the movie about?!</p><blockquote><p>你是电影的主角？太棒了！这部电影是关于什么的？！</p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s called Shutter Speed, it&#39;s really cool! Yeah, umm, I meet this girl in the subway and we fall in love in like a day, right? And then, she disappears… But I find out where she lives and when I get there this like old lady answers the door and I say, &quot;Where&#39;s Betsy?&quot; Right? And she says, &quot;Betsy&#39;s been dead for 10 years.&quot;</p><blockquote><p>这叫快门速度，真的很酷！是的，嗯，我在地铁里遇到了一个女孩，我们相爱了一天，对吧？然后，她消失了…但我找到了她住的地方，当我到了那里，一个老太太开门，我说，“贝琪在哪里？”对吗？她说，“贝琪已经死了10年了。”</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh-oh, chilling!</p><blockquote><p>哦，哦，真冷！</p></blockquote><p><strong>Joey Tribbiani:</strong> And the best part is, we&#39;re filming in the desert outside Vegas! (To Chandler) And you know what that means buddy!</p><blockquote><p>最棒的是，我们正在拉斯维加斯外的沙漠里拍摄！（对钱德勒）你知道那意味着什么，伙计！</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, I know that means buddy!</p><blockquote><p>是的，我知道那意味着老兄！</p></blockquote><p><strong>Joey Tribbiani:</strong> Road trip! Yeah, we can rent a car! I just have to be there by Tuesday!</p><blockquote><p>公路旅行！是的，我们可以租一辆车！我必须在星期二之前赶到那里！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh wait, my grandmother&#39;s dead.</p><blockquote><p>哦，等等，我祖母死了。</p></blockquote><p><strong>Chandler Bing:</strong> Well, uh, we can talk about that too Pheebs.</p><blockquote><p>嗯，嗯，我们也可以谈谈这个，菲比。</p></blockquote><p><strong>Phoebe Buffay:</strong> No! No, her cab! She probably won&#39;t be using it; you can drive it to Las Vegas.</p><blockquote><p>不！不，是她的出租车！她可能不会使用它；你可以开车去拉斯维加斯。</p></blockquote><p><strong>Joey Tribbiani:</strong> All right! Thanks Pheebs!</p><blockquote><p>好吧！谢谢菲比！</p></blockquote><p><strong>Chandler Bing:</strong> Whoa-whoa-whoa, what are we going to do about my job?</p><blockquote><p>哇，哇，我们该怎么处理我的工作？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh umm, not go.</p><blockquote><p>哦，嗯，不去。</p></blockquote><p><strong>Chandler Bing:</strong> All right, great, road trip baby! (To Monica) This okay with you?</p><blockquote><p>好吧，太好了，旅途宝贝！（对莫妮卡）你同意吗？</p></blockquote><p><strong>Monica Geller:</strong> Chandler! You don&#39;t have to ask for my permission. (Quietly) You can go.</p><blockquote><p>钱德勒！你不必征求我的同意。（轻轻地）你可以走了。</p></blockquote><p><strong>Chandler Bing:</strong> Thank you.</p><blockquote><p>谢谢你。</p></blockquote><p><strong>Monica Geller:</strong> Hey Rach, come on! We&#39;re gonna be late for the eye doctor appointment!</p><blockquote><p>嘿，瑞秋，快点！眼科医生的预约我们要迟到了！</p></blockquote><p><strong>Rachel Green:</strong> (entering from her bedroom) All right! Let&#39;s get this over with! Ugh! (She walks by the table and notices that no one is looking and accidentally on purpose knocks over the open cereal box.) Ohhh! No! Look what I did! (She starts walking through the mess. {Also, notice the continuity error in this scene. Note the position of the box and dispersal pattern of the cereal before and after the camera cut.}) Oh, I mean, look at this mess! I mean, we&#39;re probably gonna have to clean this up! Y&#39;know? We&#39;re gonna have to reschedule!</p><blockquote><p>（从卧室进来）好吧！让我们结束这一切吧！啊！（她走过桌子，注意到没有人在看，无意中打翻了打开的麦片盒。）！不看看我做了什么！（她开始在混乱中穿行。{另外，注意这个场景中的连续性错误。注意盒子的位置以及镜头切割前后谷物的分散模式。}）哦，我的意思是，看看这个混乱！我是说，我们可能得把它清理干净！你知道吗？我们得重新安排！</p></blockquote><p><strong>Monica Geller:</strong> No. If you thought this mess is going to bother me, you are wrong! All right, let&#39;s go Blinky! (She ushers Rachel out the door, but before the door fully closes she sticks her head back in.) Chandler!!!! (Chandler agrees to clean up the mess.)</p><blockquote><p>不。如果你认为这一团糟会困扰我，那你就错了！好了，我们走吧，布林奇！（她领着瑞秋出门，但在门完全关上之前，她把头伸了进去。）钱德勒！！！！（钱德勒同意收拾残局。）</p></blockquote><hr><p>🎬 <em>Central Perk, Joey is reading a map as Phoebe enters.</em></p><blockquote><p>🎬 <em>中央公园，菲比进来时，乔伊正在看地图。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Oh hey Joey! What&#39;s up?</p><blockquote><p>哦，嘿，乔伊！怎么了？</p></blockquote><p><strong>Joey Tribbiani:</strong> I can&#39;t decide which route to take to Vegas. Hey, you&#39;ve traveled a lot right?</p><blockquote><p>我决定不了去维加斯的路线。嘿，你去过很多地方，对吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, I&#39;ve been around.</p><blockquote><p>是的，我一直在附近。</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay, so-so which route should I take the northern route or the southern route?</p><blockquote><p>好吧，那我该走哪条路线，北方路线还是南方路线？</p></blockquote><p><strong>Phoebe Buffay:</strong> Ooh, if you take the northern route there&#39;s a man in Illinois with a beard of bees. {Okay, I must protest this, I&#39;ve lived in Illinois all my life and know of no man with a beard of bees! Wisconsin, on the other hand, might be a different story.}</p><blockquote><p>哦，如果你走北方路线，伊利诺伊州有一个留着蜜蜂胡子的男人。{好吧，我必须对此表示抗议，我一辈子都住在伊利诺伊州，还不知道有人留着蜜蜂的胡子！另一方面，威斯康星州可能是另一回事。}</p></blockquote><p><strong>Joey Tribbiani:</strong> Great! Problem solved!</p><blockquote><p>太好了！问题解决了！</p></blockquote><p><strong>Phoebe Buffay:</strong> But on the southern route there&#39;s a chicken that plays tic-tac-toe.</p><blockquote><p>但是在南线有一只鸡在玩抽搐。</p></blockquote><p><strong>Joey Tribbiani:</strong> Well, back to square one.</p><blockquote><p>好吧，回到原点。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, I know a way that you can decide! All right, I&#39;m going to ask you a series of questions and you answer as quickly as you can.</p><blockquote><p>哦，我知道一个你可以决定的方法！好的，我会问你一系列问题，你尽快回答。</p></blockquote><p><strong>Joey Tribbiani:</strong> (quickly) Yes!</p><blockquote><p>（快速）是的！</p></blockquote><p><strong>Phoebe Buffay:</strong> Good, but wait. Okay, all right, here we go. Now I want you to relax. Take a deep breath. Clear your mind. (Quickly) Which do you like better peanut butter or egg whites?</p><blockquote><p>很好，但是等等。好了，好了，开始吧。现在我要你放松。深呼吸。头脑清醒。（快速）你喜欢花生酱还是蛋清？</p></blockquote><p><strong>Joey Tribbiani:</strong> Peanut butter!</p><blockquote><p>花生酱！</p></blockquote><p><strong>Phoebe Buffay:</strong> Which would you rather be a fireman or a swimmer?</p><blockquote><p>你想当消防员还是游泳运动员？</p></blockquote><p><strong>Joey Tribbiani:</strong> A swimmer!</p><blockquote><p>游泳运动员！</p></blockquote><p><strong>Phoebe Buffay:</strong> Who would you rather sleep with Monica or Rachel?</p><blockquote><p>你更愿意和莫妮卡或瑞秋睡在一起？</p></blockquote><p><strong>Joey Tribbiani:</strong> Monica. Oh… huh, I always thought it would be Rachel.</p><blockquote><p>莫妮卡。我一直以为是瑞秋。</p></blockquote><p><strong>Phoebe Buffay:</strong> No thinking! No thinking! Tie or ascot?</p><blockquote><p>别想了！别想了！领带还是阿斯科特？</p></blockquote><p><strong>Joey Tribbiani:</strong> Ascot!</p><blockquote><p>阿斯科特！</p></blockquote><p><strong>Phoebe Buffay:</strong> North route or south route?</p><blockquote><p>北路还是南路？</p></blockquote><p><strong>Joey Tribbiani:</strong> North route!</p><blockquote><p>北路！</p></blockquote><p><strong>Phoebe Buffay:</strong> Bamn! There you go! Huh?</p><blockquote><p>砰！好了！嗯？</p></blockquote><p><strong>Joey Tribbiani:</strong> Wow! That was incredible! Beard of bees, here I come!</p><blockquote><p>哇！太不可思议了！蜜蜂的胡子，我来了！</p></blockquote><p><strong>Ross Geller:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, this guy again. (She ignores him.)</p><blockquote><p>哦，又是这个家伙。（她不理他。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey man, what&#39;s up?</p><blockquote><p>嘿，伙计，怎么了？</p></blockquote><p><strong>Ross Geller:</strong> Uhh, not much. You guys want to see a movie tonight?</p><blockquote><p>嗯，不多。你们今晚想看电影吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Sure, what do you want to see?</p><blockquote><p>当然，你想看什么？</p></blockquote><p><strong>Ross Geller:</strong> I don&#39;t know, umm…</p><blockquote><p>我不知道，嗯…</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, I know how we can decide. Phoebe, show him your game!</p><blockquote><p>哦，我知道我们怎么决定。菲比，让他看看你的游戏！</p></blockquote><p><strong>Phoebe Buffay:</strong> Umm, no thank you. (She gets up and moves to the couch. They were at a table previously.)</p><blockquote><p>嗯，不，谢谢。（她站起来，走向沙发。他们以前在一张桌子旁。）</p></blockquote><p><strong>Ross Geller:</strong> What&#39;s with her?</p><blockquote><p>她怎么了？</p></blockquote><p><strong>Joey Tribbiani:</strong> I don&#39;t know. But hey, I know we can decide. Okay, I&#39;m gonna ask you questions and you answer real quick. Okay?</p><blockquote><p>我不知道。但是，嘿，我知道我们可以决定。好吧，我会问你问题，你回答得很快。可以</p></blockquote><p><strong>Ross Geller:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Joey Tribbiani:</strong> What do you like better action or comedy?</p><blockquote><p>你更喜欢什么动作片还是喜剧？</p></blockquote><p><strong>Ross Geller:</strong> Action.</p><blockquote><p>行动。</p></blockquote><p><strong>Joey Tribbiani:</strong> Who would you rather sleep with Monica or Rachel?</p><blockquote><p>你更愿意和莫妮卡还是瑞秋睡？</p></blockquote><p><em>(Ross pauses and looks at him, Joey motions for him to hurry up.)</em></p><blockquote><p><em>（罗斯停下来看着他，乔伊示意他快点。）</em></p></blockquote><p><strong>Ross Geller:</strong> Dude, you are sick.</p><blockquote><p>老兄，你病了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, I&#39;m sorry. I forgot you had that whole Rachel thing.</p><blockquote><p>哦，对不起。我忘了你和瑞秋的事。</p></blockquote><hr><p>🎬 <em>Monica&#39;s eye doctor&#39;s office, Monica and Rachel are waiting in an exam room and looking at this big white thing used to check eyes. I have no idea what it is, and if an ophthalmologist happens to know what that is, let me know.</em></p><blockquote><p>🎬 <em>莫妮卡的眼科医生办公室，莫妮卡和瑞秋在检查室等着，看着这个用来检查眼睛的白色大东西。我不知道它是什么，如果眼科医生碰巧知道它是什么，请告诉我。</em></p></blockquote><p><strong>Rachel Green:</strong> Oh my God! What does that thing do?</p><blockquote><p>我的天啊！那东西是干什么用的？</p></blockquote><p><strong>Monica Geller:</strong> (looks at it more closely) Oh that&#39;s an eye removal machine.</p><blockquote><p>（更仔细地看）哦，那是一台眼球摘除机。</p></blockquote><p><strong>Rachel Green:</strong> All right, I&#39;m outta here!</p><blockquote><p>好吧，我要走了！</p></blockquote><p><strong>Monica Geller:</strong> I&#39;m kidding! I&#39;m kidding!</p><blockquote><p>我在开玩笑！我在开玩笑！</p></blockquote><p><em>(Rachel heads for the door but is intercepted by the doctor.)</em></p><blockquote><p><em>（瑞秋朝门口走去，但被医生拦住了。）</em></p></blockquote><p><strong>The Doctor:</strong> Hi Rachel!</p><blockquote><p>嗨，瑞秋！</p></blockquote><p><strong>Rachel Green:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>The Doctor:</strong> I&#39;m Dr. Miller. Monica told me you were a little nervous, but don&#39;t worry everything&#39;s gonna be just fine.</p><blockquote><p>我是米勒医生。莫妮卡告诉我你有点紧张，但别担心一切都会好起来的。</p></blockquote><p><strong>Rachel Green:</strong> So were done then!</p><blockquote><p>那我们就完了！</p></blockquote><p>Dr. Miller: Almost! But first, we gotta start.</p><blockquote><p>差不多了！但首先，我们必须开始。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p>Dr. Miller: This is a glaucoma test.</p><blockquote><p>这是青光眼检查。</p></blockquote><p><strong>Rachel Green:</strong> Uh-huh.</p><blockquote><p>嗯。</p></blockquote><p>Dr. Miller: Sit down.</p><blockquote><p>请坐。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p>Dr. Miller: But your chin here. (She does so.) Now, you&#39;ll feel a small puff of air in each eye.</p><blockquote><p>但是你的下巴在这里。（她这样做了。）现在，你会感觉到每只眼睛里都有一小口空气。</p></blockquote><p><strong>Rachel Green:</strong> (jerks back from the tester) What?!</p><blockquote><p>（从测试员那里猛然回过身）什么？！</p></blockquote><p><strong>Monica Geller:</strong> A small puff of air, now come on!</p><blockquote><p>一小口空气，来吧！</p></blockquote><p>Dr. Miller: Here we go.</p><blockquote><p>开始了。</p></blockquote><p><strong>Rachel Green:</strong> All right.</p><blockquote><p>好的。</p></blockquote><p>Dr. Miller: 1…2…3! (Rachel jerks back on 3.)</p><blockquote><p>1…2…3！（瑞秋在第三节猛地一跳。）</p></blockquote><p><strong>Rachel Green:</strong> I&#39;m sorry. All right, I&#39;ll just stay in here this time. (Puts her head back.) Okay.</p><blockquote><p>对不起。好吧，这次我就呆在这里。（把头往后仰）好的。</p></blockquote><p>Dr. Miller: Ready?</p><blockquote><p>准备好了吗？</p></blockquote><p><strong>Rachel Green:</strong> Uh-huh.</p><blockquote><p>嗯。</p></blockquote><p>Dr. Miller: 1…2… (She flinches on 2 this time.)</p><blockquote><p>1…2…（这次她在2上退缩了。）</p></blockquote><p><strong>Monica Geller:</strong> Y&#39;know what, I&#39;m gonna hold her head.</p><blockquote><p>你知道吗，我要抱着她的头。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p>Dr. Miller: That&#39;s okay.</p><blockquote><p>没关系。</p></blockquote><p><strong>Monica Geller:</strong> Okay. (Monica backs off.)</p><blockquote><p>好的。（莫妮卡退后了。）</p></blockquote><p><strong>Rachel Green:</strong> Okay. Okay!</p><blockquote><p>好的。可以</p></blockquote><p>Dr. Miller: 1…2! (She flinches again.) (Gives up.) Y&#39;know what? You&#39;re young; you probably don&#39;t have glaucoma.</p><blockquote><p>1…2！（她又退缩了。）（放弃了。）你知道吗？你还年轻；你可能没有青光眼。</p></blockquote><p><strong>Rachel Green:</strong> (really excited) Great!! It was very, very nice to meet you sir--Ow! Hey! What are you doing?! Are you crazy! (He took out that thing they use to look at people&#39;s retinas and looked at Rachel&#39;s when she was shaking his hand causing her to flinch and scream at him.)</p><blockquote><p>（真的很兴奋）太棒了！！很高兴见到你，先生——噢！嘿你在做什么？你疯了吗！（他拿出他们用来观察人们视网膜的东西，看着瑞秋的，瑞秋在和他握手时吓了一跳，对着他尖叫。）</p></blockquote><p>Dr. Miller: Okay. You&#39;ve got a small, minor infection in that left eye. I want you to take these drops three times a day and you&#39;ll be as good as new.</p><blockquote><p>好的。你的左眼有轻微的感染。我要你一天服三次这些药水，你就会跟新的一样好。</p></blockquote><p><strong>Rachel Green:</strong> Yeah, no, I don&#39;t-I don&#39;t put things in my eye.</p><blockquote><p>是的，不，我不，我不把东西放在眼睛里。</p></blockquote><p>Dr. Miller: Okay then, I guess we&#39;ll see you back here in three months.</p><blockquote><p>好吧，我想三个月后我们会在这里见到你。</p></blockquote><p><strong>Rachel Green:</strong> Great!</p><blockquote><p>太好了！</p></blockquote><p>Dr. Miller: And I&#39;ll fit you for a glass eye.</p><blockquote><p>我给你装一只玻璃眼睛。</p></blockquote><p><strong>Rachel Green:</strong> Okay, just give me the damn drops! (Grabs them and storms out.)</p><blockquote><p>好吧，把该死的药水给我！（抓住他们，冲出去。）</p></blockquote><p><strong>Monica Geller:</strong> Dr. Miller? (She covers her right eye and reads from the chart) P E C F D.</p><blockquote><p>米勒医生？（她捂住右眼，从图表中读出）P E C F D。</p></blockquote><p>Dr. Miller: Very good Monica! You know where they are.</p><blockquote><p>很好，莫妮卡！你知道他们在哪里。</p></blockquote><p><strong>Monica Geller:</strong> I sure do! (She runs over to a drawer, opens it, and grabs a lollipop.) (To Rachel) And you don&#39;t get one!</p><blockquote><p>我当然喜欢！（她跑向一个抽屉，打开抽屉，抓起一个棒棒糖。）（对瑞秋）你却一个也没有！</p></blockquote><hr><p>🎬 <em>Central Perk, Phoebe, Rachel, Monica, and Joey are there.</em></p><blockquote><p>🎬 <em>中央公园、菲比、瑞秋、莫妮卡和乔伊在那里</em></p></blockquote><p><strong>Rachel Green:</strong> Y&#39;know, I-I gotta tell ya, those eye drops are a miracle. My eye is a 100% better.</p><blockquote><p>我得告诉你，那些眼药水真是个奇迹。我的眼睛100%好了。</p></blockquote><p><strong>Monica Geller:</strong> They&#39;re still in my coat.</p><blockquote><p>它们还在我的外套里。</p></blockquote><p><strong>Rachel Green:</strong> Damn!</p><blockquote><p>该死！</p></blockquote><p><strong>Chandler Bing:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey! You ready to go?</p><blockquote><p>嘿！你准备好出发了吗？</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, listen, how cold is it going to be there? Do I need a coat or will all these sweater vests be enough? (Holds up 3 of them in different colors.)</p><blockquote><p>是的，听着，那里会有多冷？我需要一件外套还是这些毛衣背心就够了？（以不同颜色显示其中3个。）</p></blockquote><p><em>(Monica stares at him.)</em></p><blockquote><p><em>（莫妮卡盯着他。）</em></p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Monica Geller:</strong> I love you.</p><blockquote><p>我爱你。</p></blockquote><p>{There&#39;s another continuity error here. Before Monica says I love you, Chandler&#39;s holding the vests so that you couldn&#39;t see the collar, you could see all three, and they were folding nicely. After she says the line and the camera cuts back to Chandler, you can only see two out of the three, you can see the collar of the top one, and it looks like it was folded sloppily, unlike before. Hey, you notice things while spending this much time on this!}</p><blockquote><p>{这里还有一个连续性错误。在莫妮卡说我爱你之前，钱德勒拿着背心，这样你就看不到衣领了，你可以看到所有的三件衣服，它们都折叠得很好。在她说线和相机切回钱德勒之后，你只能看到三件衣服中的两件，你可以看到上面一件的衣领，看起来像和以前不同，它折叠得很松散。嘿，你花这么多时间在这上面的时候注意到了一些东西！}</p></blockquote><p><strong>Joey Tribbiani:</strong> Man, I wish Ross was coming with us! Y&#39;know? I&#39;m gonna miss him!</p><blockquote><p>伙计，我真希望罗斯和我们一起去！你知道吗？我会想念他的！</p></blockquote><p><strong>Phoebe Buffay:</strong> Thanks a lot! I just got that jerk out of my mind!</p><blockquote><p>非常感谢！我刚把那个混蛋忘了！</p></blockquote><p><strong>Chandler Bing:</strong> Hey, so where are we staying? Is the movie putting us up in a big hotel suite?</p><blockquote><p>嘿，我们住在哪里？这部电影把我们安排在一个大的酒店套房里吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh no, not really. It&#39;s an independent film y&#39;know? So we don&#39;t have a real big budget. I figured I&#39;d just stay in your room.</p><blockquote><p>呃，不，不是真的。这是一部独立电影，你知道吗？所以我们没有一个真正的大预算。我想我应该呆在你的房间里。</p></blockquote><p><strong>Chandler Bing:</strong> I see, but once you get your first paycheck you&#39;ll be springing a big hotel suite, right? I mean, lead in a movie, they must be paying you a lot?</p><blockquote><p>我明白了，但一旦你拿到第一份薪水，你就会拥有一间大酒店套房，对吗？我是说，在电影里当主角，他们一定给了你很多钱？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh yeah! For every dollar Shutter Speed makes, one penny of it goes right in Joey&#39;s pocket.</p><blockquote><p>哦，是的！快门速度每赚一美元，一分钱就放在乔伊的口袋里。</p></blockquote><p><strong>Chandler Bing:</strong> So you don&#39;t get paid unless the movie makes money?</p><blockquote><p>所以，除非电影赚钱，否则你不会得到报酬？</p></blockquote><p><strong>Joey Tribbiani:</strong> Did you not hear the plot of the movie? &quot;She&#39;s been dead for ten years.&quot; I&#39;m gonna be a millionaire!</p><blockquote><p>你没听说电影的情节吗？“她已经死了十年了。”我要成为百万富翁了！</p></blockquote><p><strong>Ross Geller:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Ross Geller:</strong> I just wanna say good-bye to you guys and to see if you guys will place a little bet for me, huh? Twenty bucks on black 15.</p><blockquote><p>我只是想和你们说再见，看看你们是否愿意为我下一点赌注，嗯？黑色15的20美元。</p></blockquote><p><strong>Joey Tribbiani:</strong> You got it!</p><blockquote><p>明白了！</p></blockquote><p><strong>Ross Geller:</strong> All right!</p><blockquote><p>好吧！</p></blockquote><p><em>(Joey nods to Chandler, no way!)</em></p><blockquote><p><em>（乔伊向钱德勒点头，不可能！）</em></p></blockquote><p><strong>Chandler Bing:</strong> All right, bye-bye now!</p><blockquote><p>好吧，再见！</p></blockquote><p><strong>Phoebe Buffay:</strong> Bye!</p><blockquote><p>再见！</p></blockquote><p><strong>Rachel Green:</strong> Bye you guys!</p><blockquote><p>再见！</p></blockquote><p><strong>Joey Tribbiani:</strong> Bye-bye!</p><blockquote><p>再见！</p></blockquote><p><strong>Monica Geller:</strong> I wanna say good-bye at the car!</p><blockquote><p>我想在车上说再见！</p></blockquote><p><strong>Chandler Bing:</strong> Okay!</p><blockquote><p>好的！</p></blockquote><p><strong>Joey Tribbiani:</strong> Anybody want to say good-bye to me at the car?</p><blockquote><p>有人想在车上跟我道别吗？</p></blockquote><p><strong>Rachel Green:</strong> Oh honey, I&#39;ll say good-bye to you at the car if you don&#39;t mind the puss.</p><blockquote><p>哦，亲爱的，如果你不介意的话，我会在车上跟你道别的。</p></blockquote><p><em>(Pause.)</em></p><blockquote><p><em>（停顿。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> See ya! (Walks out.)</p><blockquote><p>再见！（走出去。）</p></blockquote><p><strong>Rachel Green:</strong> Well, wait a minute! The puss is good! It means it&#39;s healing! (Runs after him.)</p><blockquote><p>嗯，等一下！猫很好！这意味着它正在愈合！（追着他跑。）</p></blockquote><p><strong>Ross Geller:</strong> Hey Pheebs, what &#39;cha reading? (Phoebe ignores him) Pheebs? (Turns away) Hello? (He sits down next to her and she moves over a bit.) Phoebe? (He moves closer and she keeps moving away.) Phoe-Phoebe! (They end up hanging over the arm rest.) Come on! (He grabs the magazine away from her.)</p><blockquote><p>嘿，菲比，你在读什么？（菲比不理他）菲比？（转身）喂？（他坐在她旁边，她挪了挪）菲比？（他走近了，她不停地走开。）菲比！（他们最后挂在扶手上）快点！（他把杂志从她手里夺开。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, I&#39;m sorry. I didn&#39;t see you there.</p><blockquote><p>哦，对不起。我没看见你在那里。</p></blockquote><p><strong>Ross Geller:</strong> Phoebe, are you, are you mad at me, or something? &#39;Cause if are please, tell me what it is I did!</p><blockquote><p>菲比，你是生我的气还是怎么的因为如果你是，请告诉我我做了什么！</p></blockquote><p><strong>Phoebe Buffay:</strong> Well, if you don&#39;t know I can&#39;t help you.</p><blockquote><p>嗯，如果你不知道我帮不了你。</p></blockquote><p><strong>Ross Geller:</strong> Well, I don&#39;t know.</p><blockquote><p>嗯，我不知道。</p></blockquote><p><strong>Phoebe Buffay:</strong> Well, I can&#39;t help you.</p><blockquote><p>我帮不了你。</p></blockquote><p><strong>Ross Geller:</strong> Well, whatever it is I&#39;m-I&#39;m very, very sorry. Okay?</p><blockquote><p>不管是什么，我非常非常抱歉。可以</p></blockquote><p><strong>Phoebe Buffay:</strong> Apology accepted.</p><blockquote><p>接受道歉。</p></blockquote><p><strong>Ross Geller:</strong> Okay. So we&#39;re, we&#39;re good?</p><blockquote><p>好的。所以我们，我们很好？</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh-huh.</p><blockquote><p>嗯。</p></blockquote><p><strong>Ross Geller:</strong> All right. (Gets up.) I&#39;ll uh, I&#39;ll see you later, okay?</p><blockquote><p>好的。（站起来）我会呃，待会儿见，好吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> (quietly) Bye, fat ass.</p><blockquote><p>（平静地）再见，肥屁股。</p></blockquote><p><strong>Ross Geller:</strong> ALL RIGHT!! Phoebe now come on! Will you please tell me what it is I did that mad you so mad at me!</p><blockquote><p>好吧！！菲比，快点！你能告诉我是什么让你生气的是我吗！</p></blockquote><p><strong>Phoebe Buffay:</strong> I don&#39;t know! I don&#39;t remember!</p><blockquote><p>我不知道！我不记得了！</p></blockquote><p><strong>Ross Geller:</strong> Well if you can&#39;t remember, can&#39;t we just forget about this?</p><blockquote><p>如果你不记得了，我们就不能忘了这件事吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh no, I am mad at you. I know that much. But, I am sorry about the fat ass thing. You actually have a very sweet little hiney.</p><blockquote><p>哦，不，我生你的气了。我知道很多。但是，我很抱歉关于肥屁股的事。你有一个非常可爱的小海尼。</p></blockquote><p><em>(Ross isn&#39;t sure what to do with that comment.)</em></p><blockquote><p><em>（罗斯不知道该如何处理这一评论。）</em></p></blockquote><hr><p>🎬 <em>Phoebe&#39;s cab, Joey and Chandler are headed across the George Washington bridge on their way to Las Vegas. Joey is driving.</em></p><blockquote><p>🎬 <em>菲比的出租车、乔伊和钱德勒正穿过乔治华盛顿大桥前往拉斯维加斯。乔伊正在开车。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Man, I&#39;m getting pretty tired. You&#39;re might have to take over soon.</p><blockquote><p>老兄，我真的很累了。你可能很快就要接管了。</p></blockquote><p><strong>Chandler Bing:</strong> We&#39;ve been driving for a half-hour, and you haven&#39;t looked at the road once.</p><blockquote><p>我们已经开了半个小时了，你一次也没看路。</p></blockquote><p><strong>Joey Tribbiani:</strong> Don&#39;t worry, it&#39;s out there! (Just then a horn honks and Joey quickly looks at the road.) I think I just need lunch.</p><blockquote><p>别担心，它就在外面！（就在这时喇叭响了，乔伊快速地看了看路。）我想我只需要吃午饭。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Joey Tribbiani:</strong> You wanna eat? (Pulls out the twenty) My treat!</p><blockquote><p>你想吃东西吗？（拿出二十块）我请客！</p></blockquote><p><strong>Chandler Bing:</strong> Isn&#39;t that Ross&#39;s money?</p><blockquote><p>那不是罗斯的钱吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah. Okay. Ross&#39;s treat! Where do you wanna eat?</p><blockquote><p>是的。可以罗斯请客！你想在哪里吃？</p></blockquote><p><strong>Chandler Bing:</strong> I don&#39;t know.</p><blockquote><p>我不知道。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ooh, hey, I know how we can decide! All right, uh, I&#39;m gonna ask you a bunch of questions and then you have to answer real fast. Okay? So uh, clear your mind Clear it right out! Clear it out! Clear!</p><blockquote><p>哦，嘿，我知道我们该怎么决定！好吧，我要问你一大堆问题，然后你必须很快回答。可以所以，呃，清醒一下，马上清醒过来！清除它！清楚的</p></blockquote><p><strong>Chandler Bing:</strong> Okay!</p><blockquote><p>好的！</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay, uhh, would you rather be too wet or too dry?</p><blockquote><p>好吧，嗯，你宁愿太湿还是太干？</p></blockquote><p><strong>Chandler Bing:</strong> Too dry.</p><blockquote><p>太干了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Do you believe in ghosts, yes or no?</p><blockquote><p>你相信鬼吗，是还是不是？</p></blockquote><p><strong>Chandler Bing:</strong> No!</p><blockquote><p>不！</p></blockquote><p><strong>Joey Tribbiani:</strong> Is this movie gonna be my big break?</p><blockquote><p>这部电影会是我的大突破吗？</p></blockquote><p><strong>Chandler Bing:</strong> No!</p><blockquote><p>不！</p></blockquote><p><strong>Joey Tribbiani:</strong> (shocked) What?!</p><blockquote><p>（震惊）什么？！</p></blockquote><p><strong>Chandler Bing:</strong> Yes.</p><blockquote><p>是的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Dude you said, &quot;No!&quot;</p><blockquote><p>老兄，你说“不！”</p></blockquote><p><strong>Chandler Bing:</strong> I also said, &quot;Yes!&quot;</p><blockquote><p>我还说，“是的！”</p></blockquote><p><strong>Joey Tribbiani:</strong> You don&#39;t think this is going to be a big break for me?</p><blockquote><p>你不认为这对我来说是个大突破吗？</p></blockquote><p><strong>Chandler Bing:</strong> No! (Realizes) Ahhh!!!</p><blockquote><p>不！（意识到）啊哈！！！</p></blockquote><p><strong>Joey Tribbiani:</strong> I don&#39;t believe this!</p><blockquote><p>我不相信！</p></blockquote><p><strong>Chandler Bing:</strong> Look Joe, I just, I just don&#39;t want to get your hopes up real high.</p><blockquote><p>听着，乔，我只是，我只是不想让你抱太高的希望。</p></blockquote><p><strong>Joey Tribbiani:</strong> What are you talking about?! I&#39;m the lead in a movie!</p><blockquote><p>你在说什么？！我是电影的主角！</p></blockquote><p><strong>Chandler Bing:</strong> They&#39;re not even paying ya! This doesn&#39;t even sound like a real movie!</p><blockquote><p>他们甚至不付钱给你！这听起来不像一部真正的电影！</p></blockquote><p><strong>Joey Tribbiani:</strong> Y&#39;know what? I don&#39;t need this! Okay? I don&#39;t know why you&#39;re dumping all over my big break.</p><blockquote><p>你知道吗？我不需要这个！可以我不知道你为什么把我的大突破都甩了。</p></blockquote><p><strong>Chandler Bing:</strong> Joe, I don&#39;t think this is going to be your big break.</p><blockquote><p>乔，我不认为这是你的大突破。</p></blockquote><p><strong>Joey Tribbiani:</strong> Is that why you&#39;re on this trip, huh? Make me feel like a loser? &#39;Cause if it is, I&#39;ll tell ya, I-I-I&#39;d rather be alone.</p><blockquote><p>这就是你这次旅行的原因吗？让我觉得自己是个失败者？”因为如果是的话，我会告诉你，我宁愿一个人呆着。</p></blockquote><p><strong>Chandler Bing:</strong> Oh, you don&#39;t want me on the trip?</p><blockquote><p>哦，你不想让我去旅行吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Not if you&#39;re gonna be like this!</p><blockquote><p>如果你要这样就不会了！</p></blockquote><p><strong>Chandler Bing:</strong> All right, I&#39;ll tell ya what, the next time you ask me a question like that I&#39;ll lie.</p><blockquote><p>好吧，我告诉你，下次你问我这样的问题时，我会撒谎。</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah! I don&#39;t want you on the trip!</p><blockquote><p>是啊！我不想你去旅行！</p></blockquote><p><strong>Chandler Bing:</strong> All right, fine! Fine! Why don&#39;t you pull over? I&#39;ll get out right now!</p><blockquote><p>好吧，好吧！好的你为什么不靠边停车？我马上出去！</p></blockquote><p><strong>Joey Tribbiani:</strong> Fine! (He slams on the brakes, stopping the car on the bridge to the sound of numerous car horns.) Get out!</p><blockquote><p>很好！（他猛踩刹车，听到无数汽车喇叭声，汽车停在桥上。）下车！</p></blockquote><p><strong>Chandler Bing:</strong> You&#39;re not actually supposed to stop on the bridge.</p><blockquote><p>你不应该在桥上停下来。</p></blockquote><p><strong>Joey Tribbiani:</strong> Get out!!</p><blockquote><p>出去！！</p></blockquote><p><strong>Chandler Bing:</strong> All right!! (Gets out and Joey speeds away.) Wait! Wait, there&#39;s no sidewalk! Yeah, I&#39;m gonna die here.</p><blockquote><p>好吧！！（下车，乔伊飞快地跑开）等等！等等，没有人行道！是的，我会死在这里。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Central Perk, Ross, Phoebe, Rachel, and Monica are there. Ross is trying to figure out why Phoebe&#39;s mad at him.</em></p><blockquote><p>🎬 <em>中央公园、罗斯、菲比、瑞秋和莫妮卡在那里。罗斯正在试图弄清楚菲比为什么生他的气。</em></p></blockquote><p><strong>Ross Geller:</strong> Okay, are you mad at me because my hair gel smells?</p><blockquote><p>好吧，你生我的气是因为我的发胶有味道吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Ross Geller:</strong> Are you angry at me because I said your handwriting is childlike?</p><blockquote><p>你生我的气是因为我说你的笔迹很孩子气吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No that made me feel precious.</p><blockquote><p>不，那让我觉得自己很珍贵。</p></blockquote><p><strong>Monica Geller:</strong> Oh, I know! Umm, is it because he&#39;s always correcting people&#39;s grammar? Whom! Whom! Sometimes it&#39;s who!</p><blockquote><p>哦，我知道！嗯，是因为他总是纠正人们的语法吗？谁谁有时候是谁！</p></blockquote><p><strong>Ross Geller:</strong> Yeah? Sometimes it&#39;s… (Does the fist thing.)</p><blockquote><p>是吗？有时是…（做第一件事）</p></blockquote><p><strong>Rachel Green:</strong> Oh, did you beat him at a board game? He turns into such a baby when he starts to lose.</p><blockquote><p>哦，你在棋盘游戏中打败他了吗？当他开始迷路时，他就变成了这样一个婴儿。</p></blockquote><p><strong>Ross Geller:</strong> Okay, I&#39;m the baby. (Points at his eye.)</p><blockquote><p>好吧，我是孩子。（指着他的眼睛。）</p></blockquote><p><strong>Rachel Green:</strong> Eh! Stop it!</p><blockquote><p>嗯！住手！</p></blockquote><p><strong>Chandler Bing:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Monica Geller:</strong> Chandler! What are you doing here?</p><blockquote><p>钱德勒！你在这里干什么？</p></blockquote><p><strong>Ross Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Chandler Bing:</strong> Joey kicked me out of the car on the George Washington bridge!</p><blockquote><p>乔伊在乔治华盛顿大桥上把我踢出了车！</p></blockquote><p><strong>All:</strong> Why?!</p><blockquote><p>为什么？！</p></blockquote><p><strong>Chandler Bing:</strong> I don&#39;t know! He went crazy! Y&#39;know, we were playing that game where you-you ask a question and you answer it really fast.</p><blockquote><p>我不知道！他疯了！你知道，我们在玩一个游戏，你问一个问题，然后很快回答。</p></blockquote><p><strong>Phoebe Buffay:</strong> That game should not be played without my supervision.</p><blockquote><p>没有我的监督，那游戏不应该玩。</p></blockquote><p><strong>Chandler Bing:</strong> Well, I don&#39;t know what mad him so mad, y&#39;know? All I said was that uh, I didn&#39;t think this wasn&#39;t gonna be his big break, that this movie wasn&#39;t going to do anything for him, and that uh, y&#39;know it didn&#39;t sound like a real movie--Okay, he should&#39;ve pushed me off of the bridge.</p><blockquote><p>我不知道是什么让他这么生气，你知道吗？我所说的是，呃，我不认为这不会是他的重大突破，这部电影对他没有任何帮助，而且，呃，你知道这听起来不像一部真正的电影——好吧，他应该把我从桥上推下来。</p></blockquote><p><strong>Phoebe Buffay:</strong> What&#39;s in the bag?</p><blockquote><p>包里有什么？</p></blockquote><p><strong>Chandler Bing:</strong> Oh, I figured you guys would all be mad at me. So I got you some gifts that I found on the side of the road. (Looks into the bag.) Who wants the teddy bear with one leg?</p><blockquote><p>哦，我想你们都会生我的气的。所以我给你买了一些在路边发现的礼物。（看了看袋子）谁想要一条腿的泰迪熊？</p></blockquote><p><strong>Phoebe Buffay:</strong> I do!</p><blockquote><p>我知道！</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Rachel is trying to apply her eye drops while Monica looks on.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，瑞秋在莫妮卡的注视下试着滴眼药水。</em></p></blockquote><p><strong>Rachel Green:</strong> Okay. (She tilts her head back and squeezes the eyedropper. The only problem is, it&#39;s not over her eye.)</p><blockquote><p>好的。（她把头往后仰，挤压着滴管。唯一的问题是，滴管没有盖过她的眼睛。）</p></blockquote><p><strong>Monica Geller:</strong> Not even close.</p><blockquote><p>差一点。</p></blockquote><p><strong>Rachel Green:</strong> Okay, then y&#39;know what? Help me! I need help! I can&#39;t do this!</p><blockquote><p>好吧，那你知道吗？帮助我！我需要帮助！我不能这么做！</p></blockquote><p><strong>Monica Geller:</strong> Okay! All right! Let&#39;s do it!</p><blockquote><p>好的！好吧让我们做吧！</p></blockquote><p><strong>Rachel Green:</strong> All right!</p><blockquote><p>好吧！</p></blockquote><p><strong>Monica Geller:</strong> Sit down. (They sit down on the couch.)</p><blockquote><p>坐下。（他们坐在沙发上。）</p></blockquote><p><strong>Rachel Green:</strong> All right.</p><blockquote><p>好的。</p></blockquote><p><strong>Monica Geller:</strong> Put your head back.</p><blockquote><p>把头往后仰。</p></blockquote><p><strong>Rachel Green:</strong> Yes!</p><blockquote><p>是的！</p></blockquote><p><strong>Monica Geller:</strong> All right.</p><blockquote><p>好的。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Monica Geller:</strong> Now, open your eyes.</p><blockquote><p>现在，睁开你的眼睛。</p></blockquote><p><strong>Rachel Green:</strong> Okay, they are. (No they&#39;re not.)</p><blockquote><p>好的，他们是。（不，他们不是。）</p></blockquote><p><strong>Monica Geller:</strong> How many fingers am I holding up? (She&#39;s not holding any up.)</p><blockquote><p>我能举起多少根手指？（她没有拿任何东西。）</p></blockquote><p><strong>Rachel Green:</strong> (thinks) Four.</p><blockquote><p>（想）四个。</p></blockquote><p><strong>Monica Geller:</strong> Oh my God, I was thinking four.</p><blockquote><p>哦，天哪，我在想四个。</p></blockquote><p><strong>Rachel Green:</strong> Really?!</p><blockquote><p>真的吗？！</p></blockquote><p><strong>Monica Geller:</strong> Yes! All right, y&#39;know what? Why don&#39;t we start with a practice run? Okay?</p><blockquote><p>是的！好吧，你知道吗？我们为什么不从练习跑开始呢？可以</p></blockquote><p><strong>Rachel Green:</strong> Okay!</p><blockquote><p>好的！</p></blockquote><p><strong>Monica Geller:</strong> No drops!</p><blockquote><p>不要滴水！</p></blockquote><p><strong>Rachel Green:</strong> Great!</p><blockquote><p>太好了！</p></blockquote><p><strong>Monica Geller:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Monica Geller:</strong> On three, 1…2…3! (Rachel turns her head on three to avoid the drops.) Now my pillow&#39;s all wet! (She was trying to fool Rachel and squeezed the eyedropper.)</p><blockquote><p>三点，1…2…3！（瑞秋把头转向三号以免滴水。）现在我的枕头全湿了！（她试图愚弄瑞秋，捏了捏滴管。）</p></blockquote><p><strong>Rachel Green:</strong> Well, well, you said it was practice!</p><blockquote><p>好吧，好吧，你说那是练习！</p></blockquote><p><strong>Monica Geller:</strong> Then why did you move?!</p><blockquote><p>那你为什么搬家？！</p></blockquote><p><strong>Rachel Green:</strong> Because I knew you were lying!</p><blockquote><p>因为我知道你在撒谎！</p></blockquote><p><strong>Monica Geller:</strong> All right, come here! (She gets up and drags Rachel off of the couch by her legs.)</p><blockquote><p>好吧，过来！（她站起来，拉着瑞秋的腿把她从沙发上拖下来。）</p></blockquote><p><strong>Rachel Green:</strong> (as she&#39;s being dragged) What are you? Monica!! Stop it!! Oh my God! Stop it! (Monica drags her totally onto the floor and on her back.)</p><blockquote><p>（当她被拖的时候）你是什么？莫妮卡！！住手！！哦，我的上帝！住手！（莫妮卡把她完全拖到地板上和背上。）</p></blockquote><p><strong>Monica Geller:</strong> I am going… I&#39;m going--Turn it over! (Rachel rolled onto her stomach and Monica rolls her back.) I&#39;m… I am going to get these drops in your eyes. (She is holding Rachel down with both hands and has the eyedropper in her mouth.)</p><blockquote><p>我要…我要…把它翻过来！（瑞秋翻了个身，莫妮卡翻了个身。）我……我要把这些药水滴到你的眼睛里。（她双手按住瑞秋，嘴里叼着滴管。）</p></blockquote><p><strong>Rachel Green:</strong> Oh my God! You really are freakishly strong!</p><blockquote><p>我的天啊！你真的很强壮！</p></blockquote><p><em>(Monica starts biting on the eyedropper, spraying the fluid all over. But Rachel keeps turning her head back and forth and Monica keeps missing.)</em></p><blockquote><p><em>（莫妮卡开始咬滴管，把液体喷得到处都是。但是瑞秋不停地来回转头，莫妮卡不见了。）</em></p></blockquote><p><strong>Rachel Green:</strong> Monica! Stop it!</p><blockquote><p>莫妮卡！住手！</p></blockquote><p><strong>Monica Geller:</strong> (spitting out the eyedropper) Damn! It&#39;s empty!</p><blockquote><p>（吐出滴管）该死！它是空的！</p></blockquote><p>Rachel Green: Wow, y&#39;know if Joey and Chandler walked in right now, we could make a fortune! (Monica is straddling Rachel and holding her arms down. In a rather risqu� pose, at least for primetime TV.)</p><p><strong>瑞秋·格林:</strong> 哇，你知道如果乔伊和钱德勒现在进来，我们就能发大财了！（莫妮卡跨坐在瑞秋身上，两臂低着，动作有些粗鲁� 姿势，至少在黄金时段看电视。）</p><hr><p>🎬 <em>Monica and Rachel&#39;s, time lapse, Phoebe and Monica are playing cards as the phone rings.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，时间流逝，菲比和莫妮卡在打牌，电话铃响了。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Ooh that is definitely Chandler, Joey, or Ross. (Thinks) Or-or Rachel!</p><blockquote><p>哦，那肯定是钱德勒、乔伊或罗斯。（想）或者瑞秋！</p></blockquote><p><strong>Monica Geller:</strong> (answers the phone) Hello? (Listens.) (To Phoebe) It&#39;s Joey. (Phoebe&#39;s proud of herself.) (To Joey) I&#39;m so glad you called! Chandler told me what happened. Y&#39;know he&#39;s really upset about it.</p><blockquote><p>（接电话）喂？（听）（菲比）是乔伊。（菲比为自己感到骄傲。）（对乔伊）很高兴你打电话来！钱德勒告诉我发生了什么。你知道他真的很难过。</p></blockquote><p><strong>Joey Tribbiani:</strong> (on a pay phone holding a box) Not as upset as he&#39;s gonna be when he finds out what I did with his sweater vests!</p><blockquote><p>（在一个拿着盒子的公用电话上）当他发现我对他的毛衣背心做了什么时，他不会那么难过！</p></blockquote><p><strong>Monica Geller:</strong> What did you do to his sweater vests?</p><blockquote><p>你对他的毛衣背心做了什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Let&#39;s just say there&#39;s a well-dressed pack of dogs in Ohio. Hey Monica listen is-is Phoebe there? I gotta ask her something about the car.</p><blockquote><p>我们就说俄亥俄州有一群穿着考究的狗。嘿，莫妮卡，听着，菲比在吗？我得问问她关于这辆车的事。</p></blockquote><p><strong>Monica Geller:</strong> Yeah, she&#39;s here. Hold on a second. (She hands the phone to Phoebe.)</p><blockquote><p>是的，她在这里。等一下。（她把电话递给菲比。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey, dude!</p><blockquote><p>嘿，伙计！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey Pheebs! Listen, this wooden box keeps sliding out from under the seat. What-what is it?</p><blockquote><p>嘿，菲比！听着，这个木箱一直从座位下面滑出来。这是什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh that&#39;s my grandma. (Joey holds the box away from him.) And thanks Joey she&#39;s having a really great time. (Joey is happy now.)</p><blockquote><p>哦，那是我奶奶。（乔伊把盒子拿开）谢谢乔伊，她玩得很开心。（乔伊现在很高兴。）</p></blockquote><p><strong>Chandler Bing:</strong> (who has just entered) Is that Joey? Is that Joey? Let me talk to him! I wanna talk to him!</p><blockquote><p>（刚刚进来）是乔伊吗？是乔伊吗？让我和他谈谈！我想和他谈谈！</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay Joey? Chandler&#39;s here, he was wondering… (We hear the dial tone as Joey hangs up.) Okay, I guess he ran out of change.</p><blockquote><p>好吧，乔伊？钱德勒在这里，他在想……（乔伊挂断电话时我们听到拨号音。）好吧，我想他没零钱了。</p></blockquote><p><strong>Chandler Bing:</strong> Y&#39;know, he won&#39;t even talk to me. How am I going to apologize to him if he won&#39;t even talk to me?</p><blockquote><p>你知道，他甚至不跟我说话。如果他不跟我说话，我怎么向他道歉？</p></blockquote><p><strong>Monica Geller:</strong> Well, maybe you should send him something. So that when he gets to Las Vegas he&#39;ll know that you&#39;re sorry.</p><blockquote><p>嗯，也许你应该送点东西给他。这样当他到达拉斯维加斯时，他就会知道你很抱歉。</p></blockquote><p><strong>Chandler Bing:</strong> That&#39;s a good idea. I wonder where I could (Pause) get a basket of porn…</p><blockquote><p>好主意。我想知道我在哪里可以（暂停）得到一篮子色情…</p></blockquote><p><strong>Phoebe Buffay:</strong> No, don&#39;t-don&#39;t say I&#39;m sorry with porn!</p><blockquote><p>不，不要说我对色情片感到抱歉！</p></blockquote><p><strong>Chandler Bing:</strong> Really?</p><blockquote><p>真的吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Y&#39;know what you should send him? A cartoon of cigarettes. &#39;Cause that why he could trade it for protection. No. That&#39;s prison.</p><blockquote><p>你知道你应该送他什么吗？香烟的卡通画。”这就是为什么他可以用它来换取保护。不，那是监狱。</p></blockquote><p><strong>Ross Geller:</strong> (entering) Okay Pheebs, I know how we&#39;re going to figure this out. Okay, clear your mind and answer the first thing that comes into your head. Okay?</p><blockquote><p>（进来）好吧，菲比，我知道我们要怎么解决这个问题。好的，让你头脑清醒，然后回答你脑子里想的第一件事。可以</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh-hmm.</p><blockquote><p>嗯。</p></blockquote><p><strong>Ross Geller:</strong> What do you like better flora or fauna?</p><blockquote><p>你更喜欢什么动植物？</p></blockquote><p><strong>Phoebe Buffay:</strong> Fauna.</p><blockquote><p>动物。</p></blockquote><p><strong>Ross Geller:</strong> Who would you rather be Simon or Garfunkle?</p><blockquote><p>你愿意做西蒙还是加芬克尔？</p></blockquote><p><strong>Phoebe Buffay:</strong> Garfunkle.</p><blockquote><p>加芬克尔。</p></blockquote><p><strong>Ross Geller:</strong> Why are you mad at me?</p><blockquote><p>你为什么生我的气？</p></blockquote><p><strong>Phoebe Buffay:</strong> You said I was boring--Ohh!</p><blockquote><p>你说我很无聊——哦！</p></blockquote><p><strong>Ross Geller:</strong> When did I say you were boring?!</p><blockquote><p>我什么时候说过你很无聊？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh my God, I remember now! We were playing chess!</p><blockquote><p>哦，天哪，我现在想起来了！我们在下棋！</p></blockquote><p><strong>Ross Geller:</strong> Phoebe! You and I have never played chess!</p><blockquote><p>菲比！你和我从来没有下过国际象棋！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, come on! Yes, remember that time on the frozen lake? We were playing chess, you said I was boring, and then you took off your energy mask and you were Cameron Diaz! (Realizes) Okay, there&#39;s a chance this may have been a dream.</p><blockquote><p>哦，别这样！是的，还记得那次在冰冻的湖面上吗？我们在下棋，你说我很无聊，然后你摘下你的能量面具，你就是卡梅隆·迪亚兹！（意识到）好吧，这可能是个梦。</p></blockquote><hr><p>🎬 <em>The desert outside of Las Vegas, Joey is arriving and we hear the song, Name. Y&#39;know, (singing) I&#39;ve been through the desert on a horse with no name! It felt good to be out of the rain. In the desert, you can&#39;t remember your name, &#39;cause there ain&#39;t no one for to give you no pain. La…la…la-la-la, la, la, la, la-la-la. You get the idea. Anyhoo, he pulls up and stops. As he gets out of the car, he spills a huge pill of fast food containers out of the foot well.</em></p><p><strong>Joey Tribbiani:</strong> Hey-hey! Stanley! Hey-hey! You&#39;re leading man is here! Let&#39;s get to work.</p><blockquote><p>嘿嘿！斯坦利！嘿嘿！你是这里的主角！让我们开始工作吧。</p></blockquote><p><strong>Stanley:</strong> Umm, slight change of plans. We&#39;ve shut down.</p><blockquote><p>嗯，计划有点变化。我们已经关机了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Wh-what?! Why?!</p><blockquote><p>什么？！为什么？</p></blockquote><p><strong>Stanley:</strong> It&#39;s a money thing, we don&#39;t have any.</p><blockquote><p>这是钱的问题，我们没有钱。</p></blockquote><p><strong>Joey Tribbiani:</strong> (laughs) You&#39;re kidding right?</p><blockquote><p>（笑）你在开玩笑吧？</p></blockquote><p><strong>Stanley:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Joey Tribbiani:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Stanley:</strong> It-it&#39;s probably just temporary. We&#39;re hoping to get some more money soon, so if could just uh, hang out.</p><blockquote><p>这可能只是暂时的。我们希望很快能得到更多的钱，所以如果我们能，呃，出去玩的话。</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh, hang out?! How long?</p><blockquote><p>嗯，出去玩？！多久？</p></blockquote><p><strong>Stanley:</strong> I don&#39;t know. A week? Maybe two? The money will turn up! People will always wanna invest in movies! Hey, you&#39;re not rich are ya?</p><blockquote><p>我不知道。一周？也许两个？钱会来的！人们总是想投资电影！嘿，你不富有，是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> No!</p><blockquote><p>不！</p></blockquote><p><strong>Stanley:</strong> Eh, worth a shot. (Gets into his car.) Look Joey, let me know where you&#39;re staying, okay? (The car peels away.)</p><blockquote><p>嗯，值得一试。（上车）听着，乔伊，告诉我你住在哪里，好吗？（汽车脱落了。）</p></blockquote><p><em>(I think one of the grips walk up to Joey, mainly because there&#39;s a credit for The Grip. What the heck is a grip anyway?!)</em></p><blockquote><p><em>（我想其中一个握杆走到乔伊面前，主要是因为握杆有功劳。到底什么是握杆？！）</em></p></blockquote><p><strong>The Grip:</strong> Hey pal, are you Joey Tribbiani?</p><blockquote><p>嘿，伙计，你是乔伊·特里比亚尼吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>The Grip:</strong> These got left for ya. (He hands him a bunch of helium balloons.)</p><blockquote><p>这些留给你了。（他递给他一串氦气球。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Thanks. (The grip walks away.) (Reading the card.) Congratulations on your big break.</p><blockquote><p>谢谢。（把手走开了。）（读卡片。）祝贺你的大突破。</p></blockquote><p><em>(The rest of the crew start to drive away leaving Joey sad, alone, and holding his congratulatory balloons as the song comes up again. La-la-la. See, I&#39;ve been through the desert on a horse with no name! It felt good to be out of the rain! In the desert you can&#39;t remember your name, &#39;cause there ain&#39;t no one for to give you no pain. La-la-la, la, la, la…)</em></p><blockquote><p><em>（其余的船员开始开车离开，留下乔伊独自一人，拿着他的祝贺气球，歌声再次响起。啦啦啦啦。看，我骑着一匹没有名字的马穿过了沙漠！远离雨水感觉真好！在沙漠里你记不起自己的名字，因为没有人能给你带来痛苦。啦啦啦啦，啦啦，拉，拉…）</em></p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the phone is ringing.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，电话铃响了。</em></p></blockquote><p><strong>Monica Geller:</strong> (answering it) Hello?</p><blockquote><p>（接电话）喂？</p></blockquote><p><strong>Joey Tribbiani:</strong> (on phone from Vegas) Hey Monica, it&#39;s Joey!</p><blockquote><p>（从维加斯打来的电话）嘿，莫妮卡，我是乔伊！</p></blockquote><p><strong>Monica Geller:</strong> Hey Joey! Aww, you remembered even though you&#39;re a big star!</p><blockquote><p>嘿，乔伊！啊，即使你是大明星，你也记得！</p></blockquote><p><strong>Joey Tribbiani:</strong> Aw, come on! It&#39;ll be years before I forget you!</p><blockquote><p>噢，来吧！我要过好几年才会忘记你！</p></blockquote><p><strong>Monica Geller:</strong> Joey, what&#39;s it like on a movie set, huh? Do you have a dressing room? Do you have a chair with your name on it?</p><blockquote><p>乔伊，电影布景是什么样子的？有更衣室吗？你有一把写着你名字的椅子吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh, well yeah-yeah, I&#39;ve got all of that going on. Yeah, listen uh, I want you to make sure you tell Chandler that he couldn&#39;t have been more wrong! Uh-oh! I gotta go Monica, my uh, my sushi&#39;s here!</p><blockquote><p>嗯，是的，是的，我已经做了所有这些了。是的，听着，我想你一定要告诉钱德勒，他错得再错不过了！哦！我得走了，莫妮卡，我的寿司来了！</p></blockquote><p>[Cut to Joey hanging up the phone in Vegas. He&#39;s wearing a Roman gladiator&#39;s uniform and goes over to join a family to pose for a picture. You see, he&#39;s apparently taken a job at Caesar&#39;s Palace.]</p><blockquote><p>[切到乔伊在维加斯挂了电话。他穿着罗马角斗士的制服，去和一家人合影。你看，他显然在凯撒宫工作。]</p></blockquote><p><strong>Joey Tribbiani:</strong> (to the family) Sorry about that. Thanks for waitin&#39;.</p><blockquote><p>（对家人）很抱歉。谢谢你的等待。</p></blockquote><p><strong>The Husband:</strong> Okay!</p><blockquote><p>好的！</p></blockquote><p><strong>Joey Tribbiani:</strong> Everybody smile! (The picture is taken) Okay, thanks a lot! Enjoy your stay at Caesar&#39;s! We hope it&#39;s toga-rrific! (The family leaves.) Kill me. Kill me now.</p><blockquote><p>大家都笑！（照片拍摄）好的，非常感谢！祝你在凯撒饭店过得愉快！我们希望这是真的！（家人离开）杀了我。现在杀了我。</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, The gang is surrounding Rachel at key positions.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，帮派在关键位置包围瑞秋。</em></p></blockquote><p><strong>Ross Geller:</strong> Hey Rach, can you pass me the TV Guide?</p><blockquote><p>嘿，瑞秋，你能把电视指南递给我吗？</p></blockquote><p><strong>Rachel Green:</strong> Yep!</p><blockquote><p>是的！</p></blockquote><p><em>(As she moves to get it, Monica yells…)</em></p><blockquote><p><em>（莫妮卡一边走着去拿，一边大叫……）</em></p></blockquote><p><strong>Monica Geller:</strong> Go!!</p><blockquote><p>走！！</p></blockquote><p><em>(Phoebe jumps to the floor as Ross tackles Rachel off of the couch. Chandler helps push Rachel onto the floor by jumping over the back of the couch. Phoebe grabs Rachel&#39;s head to hold it still and opens Rachel&#39;s eye as Monica jumps onto Chandler&#39;s back to administer the torture--I mean medicine.)</em></p><blockquote><p><em>（罗斯把瑞秋从沙发上抱下来时，菲比跳到地板上。钱德勒跳到沙发后面，帮助瑞秋推到地板上。菲比抓住瑞秋的头不动，睁开瑞秋的眼睛，莫妮卡跳到钱德勒的背上施行酷刑——我指的是药物。）</em></p></blockquote><p><strong>Rachel Green:</strong> What?!! Stop it! Stop it! Oh my God!</p><blockquote><p>什么？！！住手！住手！哦，我的上帝！</p></blockquote><p><strong>Monica Geller:</strong> Okay! Okay! Okay! (She succeeds in getting the eye drops in and everyone climbs off of Rachel.) We&#39;ll see you in about 3 to 4 hours.</p><blockquote><p>好的！可以可以（她成功地滴下了眼药水，所有人都从瑞秋身上爬下来。）我们将在3到4小时后见。</p></blockquote><p><strong>Rachel Green:</strong> Oh! (She&#39;s trying to recover while still on the floor.)</p><blockquote><p>哦！（她还在地板上努力恢复。）</p></blockquote><p>contrl08.gif (14783 bytes)</p><blockquote><p>contrl08.gif（14783字节）</p></blockquote>`,755)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};